        "code": "class FenwickTree:\n    def __init__(self, size: int):\n        self.n = size\n        self.tree = [0] * (size + 1)\n\n    def add(self, i: int, delta: int) -> None:\n        while i <= self.n:\n            self.tree[i] += delta\n            i += i & (-i)\n\n    def query(self, i: int) -> int:\n        total = 0\n        while i > 0:\n            total += self.tree[i]\n            i -= i & (-i)\n        return total\n\n    def range_query(self, left: int, right: int) -> int:\n        return self.query(right) - self.query(left - 1)\n\nclass LazySegmentTree:\n    def __init__(self, data: list[int]):\n        self.n = len(data)\n        self.tree = [0] * (4 * self.n)\n        self.lazy = [0] * (4 * self.n)\n        if self.n > 0:\n            self._build(data, 0, 0, self.n - 1)\n\n    def _build(self, data: list[int], node: int, l: int, r: int) -> None:\n        if l == r:\n            self.tree[node] = data[l]\n            return\n        mid = (l + r) // 2\n        self._build(data, 2 * node + 1, l, mid)\n        self._build(data, 2 * node + 2, mid + 1, r)\n        self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]\n\n    def _push_down(self, node: int, l: int, r: int) -> None:\n        if self.lazy[node] != 0 and l != r:\n            mid = (l + r) // 2\n            val = self.lazy[node]\n            left, right = 2 * node + 1, 2 * node + 2\n            self.tree[left] += (mid - l + 1) * val\n            self.lazy[left] += val\n            self.tree[right] += (r - mid) * val\n            self.lazy[right] += val\n            self.lazy[node] = 0\n\n    def range_add(self, ql: int, qr: int, val: int) -> None:\n        self._range_add(0, 0, self.n - 1, ql, qr, val)\n\n    def _range_add(self, node: int, l: int, r: int, ql: int, qr: int, val: int) -> None:\n        if ql <= l and r <= qr:\n            self.tree[node] += (r - l + 1) * val\n            self.lazy[node] += val\n            return\n        if r < ql or l > qr:\n            return\n        self._push_down(node, l, r)\n        mid = (l + r) // 2\n        self._range_add(2 * node + 1, l, mid, ql, qr, val)\n        self._range_add(2 * node + 2, mid + 1, r, ql, qr, val)\n        self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]\n\n    def range_query(self, ql: int, qr: int) -> int:\n        return self._range_query(0, 0, self.n - 1, ql, qr)\n\n    def _range_query(self, node: int, l: int, r: int, ql: int, qr: int) -> int:\n        if ql <= l and r <= qr:\n            return self.tree[node]\n        if r < ql or l > qr:\n            return 0\n        self._push_down(node, l, r)\n        mid = (l + r) // 2\n        return self._range_query(2 * node + 1, l, mid, ql, qr) + self._range_query(2 * node + 2, mid + 1, r, ql, qr)\n\nclass RollbackDSU:\n    def __init__(self, size: int):\n        self.parent = list(range(size))\n        self.size = [1] * size\n        self.history = []\n\n    def find(self, x: int) -> int:\n        while self.parent[x] != x:\n            x = self.parent[x]\n        return x\n\n    def union(self, x: int, y: int) -> bool:\n        rx, ry = self.find(x), self.find(y)\n        if rx == ry:\n            self.history.append((-1, -1, False))\n            return False\n        if self.size[rx] < self.size[ry]:\n            rx, ry = ry, rx\n        self.parent[ry] = rx\n        self.size[rx] += self.size[ry]\n        self.history.append((ry, rx, True))\n        return True\n\n    def rollback(self) -> None:\n        if not self.history:\n            return\n        ry, rx, changed = self.history.pop()\n        if changed:\n            self.parent[ry] = ry\n            self.size[rx] -= self.size[ry]\n\nfrom collections import deque\n\nclass ACNode:\n    def __init__(self):\n        self.children = {}\n        self.fail = None\n        self.outputs = []\n\nclass AhoCorasickSearcher:\n    def __init__(self, patterns: list[str]):\n        self.root = ACNode()\n        for p in patterns:\n            curr = self.root\n            for ch in p:\n                if ch not in curr.children:\n                    curr.children[ch] = ACNode()\n                curr = curr.children[ch]\n            curr.outputs.append(p)\n        queue = deque()\n        for child in self.root.children.values():\n            child.fail = self.root\n            queue.append(child)\n        while queue:\n            curr = queue.popleft()\n            for ch, child in curr.children.items():\n                queue.append(child)\n                f = curr.fail\n                while f is not None and ch not in f.children:\n                    f = f.fail\n                child.fail = f.children[ch] if f is not None else self.root\n                child.outputs.extend(child.fail.outputs)\n\n    def search(self, text: str) -> list[tuple[int, str]]:\n        matches = []\n        curr = self.root\n        for idx, ch in enumerate(text):\n            while curr is not None and ch not in curr.children:\n                curr = curr.fail\n            if curr is None:\n                curr = self.root\n                continue\n            curr = curr.children[ch]\n            for pat in curr.outputs:\n                matches.append((idx - len(pat) + 1, pat))\n        return matches\n\nclass EngineOrchestrator:\n    def __init__(self, total_nodes: int, time_slots: int, signatures: list[str]):\n        self.bit = FenwickTree(total_nodes)\n        self.seg_tree = LazySegmentTree([0] * time_slots)\n        self.dsu = RollbackDSU(total_nodes)\n        self.scanner = AhoCorasickSearcher(signatures)\n\nengine = EngineOrchestrator(16, 24, [\"ERR_TIMEOUT\", \"DROP_PACKET\"])\nprint(\"Milestone 7 Orchestrator initialized:\")\nprint(\"  Fenwick counters:\", engine.bit.n)\nprint(\"  Lazy interval forecast slots:\", engine.seg_tree.n)\nprint(\"  Cluster DSU partitions:\", len(engine.dsu.parent))\nprint(\"  Signature scan hits on 'NODE1 ERR_TIMEOUT':\", engine.scanner.search(\"NODE1 ERR_TIMEOUT\"))",
