        "code": "from collections import deque\n\nclass ServiceTopologyAuditor:\n    def __init__(self, services: list[str], calls: list[tuple[str, str]]):\n        self.names = sorted(services)\n        self.idx = {name: i for i, name in enumerate(self.names)}\n        self.edges = [(self.idx[u], self.idx[v]) for u, v in calls]\n\n    def audit(self) -> dict:\n        n = len(self.names)\n        adj = [[] for _ in range(n)]\n        for u, v in self.edges:\n            adj[u].append(v)\n\n        disc, low, on_stack = [-1] * n, [0] * n, [False] * n\n        comp_id = [-1] * n\n        stack, sccs = [], []\n        timer = 0\n\n        def dfs(u: int) -> None:\n            nonlocal timer\n            disc[u] = low[u] = timer\n            timer += 1\n            stack.append(u)\n            on_stack[u] = True\n            for v in adj[u]:\n                if disc[v] == -1:\n                    dfs(v)\n                    low[u] = min(low[u], low[v])\n                elif on_stack[v]:\n                    low[u] = min(low[u], disc[v])\n            if low[u] == disc[u]:\n                cid = len(sccs)\n                members = []\n                while True:\n                    w = stack.pop()\n                    on_stack[w] = False\n                    comp_id[w] = cid\n                    members.append(self.names[w])\n                    if w == u:\n                        break\n                sccs.append(sorted(members))\n\n        for i in range(n):\n            if disc[i] == -1:\n                dfs(i)\n\n        circular_rings = [c for c in sccs if len(c) > 1]\n        in_deg = [0] * len(sccs)\n        dag_adj = [[] for _ in range(len(sccs))]\n        seen_e = set()\n        for u, v in self.edges:\n            cu, cv = comp_id[u], comp_id[v]\n            if cu != cv and (cu, cv) not in seen_e:\n                seen_e.add((cu, cv))\n                dag_adj[cu].append(cv)\n                in_deg[cv] += 1\n\n        q = deque([i for i in range(len(sccs)) if in_deg[i] == 0])\n        waves = []\n        while q:\n            wave = []\n            for _ in range(len(q)):\n                c = q.popleft()\n                wave.append(sccs[c])\n                for nxt in dag_adj[c]:\n                    in_deg[nxt] -= 1\n                    if in_deg[nxt] == 0:\n                        q.append(nxt)\n            waves.append(wave)\n\n        return {\"sccs\": sccs, \"circular_rings\": circular_rings, \"waves\": waves}\n\nservices = [\"gateway\", \"auth\", \"session\", \"orders\", \"billing\", \"ledger\", \"notify\", \"metrics\"]\ncalls = [\n    (\"gateway\", \"auth\"), (\"auth\", \"session\"), (\"session\", \"auth\"),\n    (\"gateway\", \"orders\"), (\"orders\", \"billing\"), (\"billing\", \"ledger\"), (\"ledger\", \"orders\"),\n    (\"orders\", \"notify\"), (\"notify\", \"metrics\"), (\"auth\", \"metrics\")\n]\nreport = ServiceTopologyAuditor(services, calls).audit()\nprint(f\"Total SCCs: {len(report['sccs'])}, Circular Dependency Rings: {report['circular_rings']}\")\nfor idx, w in enumerate(report[\"waves\"], 1):\n    print(f\"  Deploy Wave {idx}: {w}\")",
