        "code": "class TopologyInspector:\n    def __init__(self, nodes: list[str], directed_links: list[tuple[str, str, int]]):\n        self.nodes = sorted(set(nodes))\n        self.idx = {name: i for i, name in enumerate(self.nodes)}\n        self.n = len(self.nodes)\n        self.dir_edges = [(self.idx[u], self.idx[v]) for u, v, _ in directed_links if u != v]\n        seen = set()\n        self.undir_edges = []\n        for u, v in self.dir_edges:\n            pair = (min(u, v), max(u, v))\n            if pair not in seen:\n                seen.add(pair)\n                self.undir_edges.append(pair)\n\n    def tarjan_scc(self) -> list[list[str]]:\n        adj = [[] for _ in range(self.n)]\n        for u, v in self.dir_edges:\n            adj[u].append(v)\n        disc, low, on_stack = [-1] * self.n, [0] * self.n, [False] * self.n\n        stack, sccs, timer = [], [], 0\n\n        def dfs(u: int) -> None:\n            nonlocal timer\n            disc[u] = low[u] = timer\n            timer += 1\n            stack.append(u)\n            on_stack[u] = True\n            for v in adj[u]:\n                if disc[v] == -1:\n                    dfs(v)\n                    low[u] = min(low[u], low[v])\n                elif on_stack[v]:\n                    low[u] = min(low[u], disc[v])\n            if low[u] == disc[u]:\n                comp = []\n                while True:\n                    w = stack.pop()\n                    on_stack[w] = False\n                    comp.append(self.nodes[w])\n                    if w == u:\n                        break\n                sccs.append(sorted(comp))\n\n        for i in range(self.n):\n            if disc[i] == -1:\n                dfs(i)\n        return sorted(sccs)\n\n    def physical_spofs(self) -> tuple[list[tuple[str, str]], list[str]]:\n        adj = [[] for _ in range(self.n)]\n        for eid, (u, v) in enumerate(self.undir_edges):\n            adj[u].append((v, eid))\n            adj[v].append((u, eid))\n        disc, low, is_ap = [-1] * self.n, [0] * self.n, [False] * self.n\n        bridges, timer = [], 0\n\n        def dfs(u: int, peid: int) -> None:\n            nonlocal timer\n            disc[u] = low[u] = timer\n            timer += 1\n            children = 0\n            for v, eid in adj[u]:\n                if eid == peid:\n                    continue\n                if disc[v] != -1:\n                    low[u] = min(low[u], disc[v])\n                else:\n                    children += 1\n                    dfs(v, eid)\n                    low[u] = min(low[u], low[v])\n                    if low[v] > disc[u]:\n                        bridges.append(tuple(sorted((self.nodes[u], self.nodes[v]))))\n                    if peid != -1 and low[v] >= disc[u]:\n                        is_ap[u] = True\n            if peid == -1 and children > 1:\n                is_ap[u] = True\n\n        for i in range(self.n):\n            if disc[i] == -1:\n                dfs(i, -1)\n        return sorted(bridges), sorted(self.nodes[i] for i, f in enumerate(is_ap) if f)\n\nnodes = [\"edge-a\", \"core-1\", \"core-2\", \"core-3\", \"dist-x\", \"dist-y\"]\nlinks = [\n    (\"edge-a\", \"core-1\", 10), (\"core-1\", \"edge-a\", 10),\n    (\"core-1\", \"core-2\", 8), (\"core-2\", \"core-1\", 8),\n    (\"core-2\", \"core-3\", 6), (\"core-3\", \"core-2\", 6), (\"core-3\", \"core-1\", 5),\n    (\"core-3\", \"dist-x\", 12), (\"dist-x\", \"core-3\", 12),\n    (\"dist-x\", \"dist-y\", 7), (\"dist-y\", \"dist-x\", 7),\n]\ninspector = TopologyInspector(nodes, links)\nprint(\"Directed SCCs:\", inspector.tarjan_scc())\nb, ap = inspector.physical_spofs()\nprint(\"Physical Bridges:\", b)\nprint(\"Cut Routers:\", ap)",
