        "example": "A routing firewall rejects any new BGP preference table the instant SPFA traces a negative closed ring among peering routers.",
        "code": "from collections import deque\n\nclass PolicySolver:\n    def __init__(self, nodes: list[str], directed_links: list[tuple[str, str, int]]):\n        self.nodes = sorted(set(nodes))\n        self.idx = {name: i for i, name in enumerate(self.nodes)}\n        self.n = len(self.nodes)\n        self.adj = [[] for _ in range(self.n)]\n        for u, v, w in directed_links:\n            if u in self.idx and v in self.idx and u != v:\n                self.adj[self.idx[u]].append((self.idx[v], w))\n\n    def evaluate(self, src: str) -> dict:\n        s = self.idx[src]\n        dist = [float(\"inf\")] * self.n\n        parent = [-1] * self.n\n        in_queue = [False] * self.n\n        pushes = [0] * self.n\n        dist[s] = 0\n        q = deque([s])\n        in_queue[s] = True\n        pushes[s] = 1\n\n        while q:\n            u = q.popleft()\n            in_queue[u] = False\n            for v, w in self.adj[u]:\n                if dist[u] + w < dist[v]:\n                    dist[v] = dist[u] + w\n                    parent[v] = u\n                    if not in_queue[v]:\n                        pushes[v] += 1\n                        if pushes[v] >= self.n:\n                            curr = v\n                            for _ in range(self.n):\n                                curr = parent[curr]\n                            cyc = []\n                            anchor = curr\n                            while True:\n                                cyc.append(self.nodes[curr])\n                                if curr == anchor and len(cyc) > 1:\n                                    break\n                                curr = parent[curr]\n                            cyc.reverse()\n                            return {\"valid\": False, \"negative_cycle\": cyc, \"distances\": {}}\n                        q.append(v)\n                        in_queue[v] = True\n\n        return {\n            \"valid\": True,\n            \"negative_cycle\": [],\n            \"distances\": {self.nodes[i]: dist[i] for i in range(self.n)}\n        }\n\nnodes = [\"gw\", \"r1\", \"r2\", \"r3\", \"dc\"]\nsafe_links = [(\"gw\", \"r1\", 10), (\"r1\", \"r2\", -3), (\"r2\", \"r3\", 4), (\"r3\", \"r1\", 2), (\"r3\", \"dc\", 5)]\nprint(\"Clean Rebate Policy:\", PolicySolver(nodes, safe_links).evaluate(\"gw\"))\n\nbad_links = [(\"gw\", \"r1\", 10), (\"r1\", \"r2\", -6), (\"r2\", \"r3\", 2), (\"r3\", \"r1\", 1), (\"r3\", \"dc\", 5)]\nprint(\"Looping Rebate Policy:\", PolicySolver(nodes, bad_links).evaluate(\"gw\"))",
