        "code": "from collections import deque\n\nclass EnterpriseNetworkEngine:\n    def __init__(self, nodes: list[str], directed_links: list[tuple[str, str, int]]):\n        self.nodes = sorted(set(nodes))\n        self.idx = {name: i for i, name in enumerate(self.nodes)}\n        self.n = len(self.nodes)\n        self.dir_links = [(self.idx[u], self.idx[v], w) for u, v, w in directed_links if u != v]\n        seen = set()\n        self.undir_edges = []\n        for u, v, _ in self.dir_links:\n            p = (min(u, v), max(u, v))\n            if p not in seen:\n                seen.add(p)\n                self.undir_edges.append(p)\n\n    def _tarjan_scc(self) -> list[list[str]]:\n        adj = [[] for _ in range(self.n)]\n        for u, v, _ in self.dir_links:\n            adj[u].append(v)\n        disc, low, on_stack = [-1] * self.n, [0] * self.n, [False] * self.n\n        stack, sccs, timer = [], [], 0\n\n        def dfs(u: int) -> None:\n            nonlocal timer\n            disc[u] = low[u] = timer\n            timer += 1\n            stack.append(u)\n            on_stack[u] = True\n            for v in adj[u]:\n                if disc[v] == -1:\n                    dfs(v)\n                    low[u] = min(low[u], low[v])\n                elif on_stack[v]:\n                    low[u] = min(low[u], disc[v])\n            if low[u] == disc[u]:\n                comp = []\n                while True:\n                    w = stack.pop()\n                    on_stack[w] = False\n                    comp.append(self.nodes[w])\n                    if w == u:\n                        break\n                sccs.append(sorted(comp))\n\n        for i in range(self.n):\n            if disc[i] == -1:\n                dfs(i)\n        return sorted(sccs)\n\n    def _physical_spofs(self) -> tuple[list[tuple[str, str]], list[str]]:\n        adj = [[] for _ in range(self.n)]\n        for eid, (u, v) in enumerate(self.undir_edges):\n            adj[u].append((v, eid))\n            adj[v].append((u, eid))\n        disc, low, is_ap = [-1] * self.n, [0] * self.n, [False] * self.n\n        bridges, timer = [], 0\n\n        def dfs(u: int, peid: int) -> None:\n            nonlocal timer\n            disc[u] = low[u] = timer\n            timer += 1\n            children = 0\n            for v, eid in adj[u]:\n                if eid == peid:\n                    continue\n                if disc[v] != -1:\n                    low[u] = min(low[u], disc[v])\n                else:\n                    children += 1\n                    dfs(v, eid)\n                    low[u] = min(low[u], low[v])\n                    if low[v] > disc[u]:\n                        bridges.append(tuple(sorted((self.nodes[u], self.nodes[v]))))\n                    if peid != -1 and low[v] >= disc[u]:\n                        is_ap[u] = True\n            if peid == -1 and children > 1:\n                is_ap[u] = True\n\n        for i in range(self.n):\n            if disc[i] == -1:\n                dfs(i, -1)\n        return sorted(bridges), sorted(self.nodes[i] for i, flag in enumerate(is_ap) if flag)\n\n    def _spfa_check_global_cycles(self) -> list[str]:\n        adj = [[] for _ in range(self.n)]\n        for u, v, w in self.dir_links:\n            adj[u].append((v, w))\n        dist = [0] * self.n\n        parent = [-1] * self.n\n        in_queue = [True] * self.n\n        pushes = [1] * self.n\n        q = deque(range(self.n))\n        while q:\n            u = q.popleft()\n            in_queue[u] = False\n            for v, w in adj[u]:\n                if dist[u] + w < dist[v]:\n                    dist[v] = dist[u] + w\n                    parent[v] = u\n                    if not in_queue[v]:\n                        pushes[v] += 1\n                        if pushes[v] >= self.n:\n                            curr = v\n                            for _ in range(self.n):\n                                curr = parent[curr]\n                            cyc, anchor = [], curr\n                            while True:\n                                cyc.append(self.nodes[curr])\n                                if curr == anchor and len(cyc) > 1:\n                                    break\n                                curr = parent[curr]\n                            cyc.reverse()\n                            return cyc\n                        q.append(v)\n                        in_queue[v] = True\n        return []\n\n    def run_audit(self) -> dict:\n        sccs = self._tarjan_scc()\n        bridges, cut_routers = self._physical_spofs()\n        neg_cycle = self._spfa_check_global_cycles()\n        if neg_cycle:\n            return {\"status\": \"BLOCKED_NEG_CYCLE\", \"sccs\": sccs, \"bridges\": bridges, \"cut_routers\": cut_routers, \"neg_cycle\": neg_cycle}\n\n        INF = float(\"inf\")\n        dist = [[INF] * self.n for _ in range(self.n)]\n        nxt = [[-1] * self.n for _ in range(self.n)]\n        for i in range(self.n):\n            dist[i][i] = 0\n            nxt[i][i] = i\n        for u, v, w in self.dir_links:\n            if w < dist[u][v]:\n                dist[u][v] = w\n                nxt[u][v] = v\n        for k in range(self.n):\n            for i in range(self.n):\n                if dist[i][k] == INF:\n                    continue\n                for j in range(self.n):\n                    cand = dist[i][k] + dist[k][j]\n                    if dist[k][j] != INF and cand < dist[i][j]:\n                        dist[i][j] = cand\n                        nxt[i][j] = nxt[i][k]\n\n        hub, hub_ecc = min(((self.nodes[i], max(dist[i])) for i in range(self.n)), key=lambda x: x[1])\n        return {\"status\": \"HEALTHY_ROUTING\", \"sccs\": sccs, \"bridges\": bridges, \"cut_routers\": cut_routers, \"hub\": hub, \"eccentricity\": hub_ecc, \"dist\": dist, \"nxt\": nxt}\n\nnodes = [\"dc-east\", \"dc-core\", \"dc-west\", \"eu-gw\", \"eu-app\", \"eu-db\", \"edge-lon\"]\nlinks = [\n    (\"dc-east\", \"dc-core\", 15), (\"dc-core\", \"dc-east\", 15),\n    (\"dc-core\", \"dc-west\", 20), (\"dc-west\", \"dc-core\", 20),\n    (\"dc-west\", \"dc-east\", 25), (\"dc-east\", \"dc-west\", 25),\n    (\"dc-core\", \"eu-gw\", 70), (\"eu-gw\", \"dc-core\", 70),\n    (\"eu-gw\", \"eu-app\", 10), (\"eu-app\", \"eu-db\", 8), (\"eu-db\", \"eu-gw\", 12),\n    (\"eu-app\", \"eu-gw\", 10), (\"eu-db\", \"eu-app\", 8), (\"eu-gw\", \"eu-db\", 12),\n    (\"eu-gw\", \"edge-lon\", 14), (\"edge-lon\", \"eu-gw\", 14),\n]\nreport = EnterpriseNetworkEngine(nodes, links).run_audit()\nprint(f\"Engine Status: {report['status']}\")\nprint(f\"Directed SCCs ({len(report['sccs'])}): {report['sccs']}\")\nprint(f\"Physical Bridges: {report['bridges']}\")\nprint(f\"Cut Routers: {report['cut_routers']}\")\nprint(f\"Optimal Failover Hub: {report['hub']} (worst RTT = {report['eccentricity']} ms)\")\nidx_map = {name: i for i, name in enumerate(sorted(nodes))}\nprint(f\"dc-east -> edge-lon shortest RTT: {report['dist'][idx_map['dc-east']][idx_map['edge-lon']]} ms\")",
