        "code": "from collections import deque\n\nclass MinCostMaxFlow:\n    def __init__(self, n: int):\n        self.n = n\n        self.adj = [[] for _ in range(n)]\n\n    def add_edge(self, u: int, v: int, cap: int, cost: int) -> None:\n        self.adj[u].append([v, len(self.adj[v]), cap, cost])\n        self.adj[v].append([u, len(self.adj[u]) - 1, 0, -cost])\n\n    def solve(self, s: int, t: int, flow_limit: int = 10**18) -> tuple[int, int]:\n        total_flow = 0\n        total_cost = 0\n        INF = 10**18\n\n        while total_flow < flow_limit:\n            dist = [INF] * self.n\n            parent_v = [-1] * self.n\n            parent_e = [-1] * self.n\n            in_q = [False] * self.n\n\n            dist[s] = 0\n            q = deque([s])\n            in_q[s] = True\n\n            while q:\n                u = q.popleft()\n                in_q[u] = False\n                for idx, (v, _, cap, cost) in enumerate(self.adj[u]):\n                    if cap > 0 and dist[u] + cost < dist[v]:\n                        dist[v] = dist[u] + cost\n                        parent_v[v] = u\n                        parent_e[v] = idx\n                        if not in_q[v]:\n                            q.append(v)\n                            in_q[v] = True\n\n            if dist[t] == INF:\n                break\n\n            push = flow_limit - total_flow\n            curr = t\n            while curr != s:\n                u = parent_v[curr]\n                eidx = parent_e[curr]\n                push = min(push, self.adj[u][eidx][2])\n                curr = u\n\n            curr = t\n            while curr != s:\n                u = parent_v[curr]\n                eidx = parent_e[curr]\n                rev = self.adj[u][eidx][1]\n                self.adj[u][eidx][2] -= push\n                self.adj[curr][rev][2] += push\n                curr = u\n\n            total_flow += push\n            total_cost += push * dist[t]\n\n        return total_flow, total_cost\n\nmcmf = MinCostMaxFlow(4)\nfor u, v, cap, cost in [(0, 1, 2, 1), (0, 2, 2, 3), (1, 2, 1, 1), (1, 3, 1, 5), (2, 3, 3, 2)]:\n    mcmf.add_edge(u, v, cap, cost)\n\nmax_f, min_c = mcmf.solve(0, 3)\nprint(f\"Unbounded MCMF: Max Flow = {max_f}, Min Cost = {min_c}\")",
