        "code": "def edit_distance_ops(s1: str, s2: str) -> tuple[int, list[str]]:\n    m, n = len(s1), len(s2)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    for i in range(m + 1):\n        dp[i][0] = i\n    for j in range(n + 1):\n        dp[0][j] = j\n\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if s1[i - 1] == s2[j - 1]:\n                dp[i][j] = dp[i - 1][j - 1]\n            else:\n                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])\n\n    ops = []\n    i, j = m, n\n    while i > 0 or j > 0:\n        if i > 0 and j > 0 and s1[i - 1] == s2[j - 1]:\n            i -= 1\n            j -= 1\n        elif i > 0 and j > 0 and dp[i][j] == dp[i - 1][j - 1] + 1:\n            ops.append(f\"replace '{s1[i-1]}'->'{s2[j-1]}' at pos {i-1}\")\n            i -= 1\n            j -= 1\n        elif i > 0 and dp[i][j] == dp[i - 1][j] + 1:\n            ops.append(f\"delete '{s1[i-1]}' at pos {i-1}\")\n            i -= 1\n        else:\n            ops.append(f\"insert '{s2[j-1]}'\")\n            j -= 1\n    ops.reverse()\n    return dp[m][n], ops\n\nd, trace = edit_distance_ops(\"intention\", \"execution\")\nprint(f\"Levenshtein Distance('intention', 'execution') = {d}\")\nfor op in trace:\n    print(\" \", op)",
