        "example": "A freight dispatcher checks total highway tonnage across a bridge network with tollbooth caps before committing delivery schedules.",
        "code": "from collections import deque\n\nclass NetworkThroughputVerifier:\n    def __init__(self, target_gbps: int):\n        self.target_gbps = target_gbps\n        self.nodes = {}\n        self.names = []\n        self.edges = []\n\n    def _id(self, name: str) -> int:\n        if name not in self.nodes:\n            self.nodes[name] = len(self.names)\n            self.names.append(name)\n        return self.nodes[name]\n\n    def add_pipe(self, u: str, v: str, cap: int, label: str) -> None:\n        self.edges.append((self._id(u), self._id(v), cap, label))\n\n    def verify(self, src: str, sink: str) -> dict:\n        s, t = self._id(src), self._id(sink)\n        n = len(self.names)\n        adj = [[] for _ in range(n)]\n        for u, v, c, _ in self.edges:\n            adj[u].append([v, len(adj[v]), c])\n            adj[v].append([u, len(adj[u]) - 1, 0])\n\n        level = [-1] * n\n        def bfs() -> bool:\n            for i in range(n):\n                level[i] = -1\n            level[s] = 0\n            q = deque([s])\n            while q:\n                u = q.popleft()\n                for v, _, cap in adj[u]:\n                    if level[v] == -1 and cap > 0:\n                        level[v] = level[u] + 1\n                        q.append(v)\n            return level[t] != -1\n\n        def dfs(u: int, pushed: int, ptr: list[int]) -> int:\n            if pushed == 0 or u == t:\n                return pushed\n            while ptr[u] < len(adj[u]):\n                v, rev, cap = adj[u][ptr[u]]\n                if level[v] == level[u] + 1 and cap > 0:\n                    tr = dfs(v, min(pushed, cap), ptr)\n                    if tr > 0:\n                        adj[u][ptr[u]][2] -= tr\n                        adj[v][rev][2] += tr\n                        return tr\n                ptr[u] += 1\n            return 0\n\n        max_f = 0\n        while bfs():\n            ptr = [0] * n\n            while True:\n                p = dfs(s, 10**18, ptr)\n                if p == 0:\n                    break\n                max_f += p\n\n        min_cut = sorted((lbl, c) for u, v, c, lbl in self.edges if level[u] != -1 and level[v] == -1)\n        return {\"max_gbps\": max_f, \"meets_sla\": max_f >= self.target_gbps, \"bottlenecks\": min_cut}\n\nv = NetworkThroughputVerifier(target_gbps=55)\nv.add_pipe(\"S\", \"ing_a\", 40, \"in:a\")\nv.add_pipe(\"S\", \"ing_b\", 35, \"in:b\")\nv.add_pipe(\"ing_a\", \"hub_in\", 40, \"fiber:a->hub\")\nv.add_pipe(\"ing_b\", \"hub_in\", 35, \"fiber:b->hub\")\nv.add_pipe(\"hub_in\", \"hub_out\", 50, \"router:hub_cpu\")\nv.add_pipe(\"hub_out\", \"T\", 60, \"egress:T\")\nprint(\"Stage 1 Dinic Gate:\", v.verify(\"S\", \"T\"))",
