        "code": "class EulerSparseTableLCA:\n    def __init__(self, n: int, edges: list[tuple[int, int]], root: int = 0):\n        adj = [[] for _ in range(n)]\n        for u, v in edges:\n            adj[u].append(v)\n            adj[v].append(u)\n\n        self.euler = []\n        self.depths = []\n        self.first_occ = [-1] * n\n        depth_arr = [0] * n\n\n        # Iterative Euler walk emitting (node, depth) on every step down AND return up!\n        stack = [(root, -1, 0)]  # state 0=visit, 1=child iteration via iter index\n        child_idx = [0] * n\n        parent_arr = [-1] * n\n\n        def push_euler(u: int) -> None:\n            if self.first_occ[u] == -1:\n                self.first_occ[u] = len(self.euler)\n            self.euler.append(u)\n            self.depths.append(depth_arr[u])\n\n        cur = root\n        push_euler(cur)\n        while True:\n            nbrs = adj[cur]\n            if child_idx[cur] < len(nbrs):\n                nxt = nbrs[child_idx[cur]]\n                child_idx[cur] += 1\n                if nxt != parent_arr[cur]:\n                    parent_arr[nxt] = cur\n                    depth_arr[nxt] = depth_arr[cur] + 1\n                    cur = nxt\n                    push_euler(cur)\n            else:\n                if cur == root:\n                    break\n                cur = parent_arr[cur]\n                push_euler(cur)\n\n        # Build Sparse Table over (depth, node) pairs on Euler walk of size M = 2N - 1\n        m = len(self.euler)\n        self.logs = [0] * (m + 1)\n        for i in range(2, m + 1):\n            self.logs[i] = self.logs[i >> 1] + 1\n        max_k = self.logs[m] + 1\n        self.st = [[(self.depths[i], self.euler[i]) for i in range(m)]]\n        for k in range(1, max_k):\n            step = 1 << (k - 1)\n            prev_row = self.st[k - 1]\n            cur_row = [min(prev_row[i], prev_row[i + step]) for i in range(m - (1 << k) + 1)]\n            self.st.append(cur_row)\n\n    def query_o1(self, u: int, v: int) -> int:\n        l, r = self.first_occ[u], self.first_occ[v]\n        if l > r:\n            l, r = r, l\n        k = self.logs[r - l + 1]\n        _, ans_node = min(self.st[k][l], self.st[k][r - (1 << k) + 1])\n        return ans_node\n\nedges = [(0, 1), (0, 2), (1, 3), (1, 4), (4, 5), (2, 6), (6, 7)]\nrmq_lca = EulerSparseTableLCA(8, edges, root=0)\nprint(\"Euler Walk Nodes:\", rmq_lca.euler)\nfor u, v in [(3, 5), (5, 7), (4, 5), (6, 7)]:\n    print(f\"O(1) RMQ LCA({u}, {v}) = {rmq_lca.query_o1(u, v)}\")",
