        "example": "A robotics warehouse encloses restricted construction cones inside one convex polygon, verifying immediately whether drone waypoint transitions touch boundary edges or violate interior space.",
        "code": "import math\n\nclass GeofenceGeometryEngine:\n    def __init__(self, hazards: list[tuple[int, int]]):\n        self.hull = self._build_hull(hazards)\n\n    @staticmethod\n    def _cross(o: tuple[int, int], a: tuple[int, int], b: tuple[int, int]) -> int:\n        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])\n\n    @classmethod\n    def _build_hull(cls, points: list[tuple[int, int]]) -> list[tuple[int, int]]:\n        pts = sorted(set(points))\n        if len(pts) <= 1:\n            return pts\n        lo, hi = [], []\n        for p in pts:\n            while len(lo) >= 2 and cls._cross(lo[-2], lo[-1], p) <= 0: lo.pop()\n            lo.append(p)\n        for p in reversed(pts):\n            while len(hi) >= 2 and cls._cross(hi[-2], hi[-1], p) <= 0: hi.pop()\n            hi.append(p)\n        return lo[:-1] + hi[:-1]\n\n    def contains_point(self, p: tuple[int, int]) -> bool:\n        m = len(self.hull)\n        if m < 3:\n            return False\n        for i in range(m):\n            if self._cross(self.hull[i], self.hull[(i + 1) % m], p) < 0:\n                return False\n        return True\n\n    def _seg_intersect(self, a: tuple[int, int], b: tuple[int, int], c: tuple[int, int], d: tuple[int, int]) -> bool:\n        def sgn(x: int) -> int: return 1 if x > 0 else (-1 if x < 0 else 0)\n        def on_seg(p, q, r): return min(p[0], r[0]) <= q[0] <= max(p[0], r[0]) and min(p[1], r[1]) <= q[1] <= max(p[1], r[1])\n        o1, o2 = sgn(self._cross(a, b, c)), sgn(self._cross(a, b, d))\n        o3, o4 = sgn(self._cross(c, d, a)), sgn(self._cross(c, d, b))\n        if o1 != o2 and o3 != o4: return True\n        return (o1 == 0 and on_seg(a, c, b)) or (o2 == 0 and on_seg(a, d, b)) or (o3 == 0 and on_seg(c, a, d)) or (o4 == 0 and on_seg(c, b, d))\n\n    def route_breaches_zone(self, start: tuple[int, int], end: tuple[int, int]) -> bool:\n        if self.contains_point(start) or self.contains_point(end):\n            return True\n        m = len(self.hull)\n        return any(self._seg_intersect(start, end, self.hull[i], self.hull[(i + 1) % m]) for i in range(m))\n\n    def report_footprint(self) -> dict:\n        m = len(self.hull)\n        area2 = sum(self.hull[i][0] * self.hull[(i + 1) % m][1] - self.hull[(i + 1) % m][0] * self.hull[i][1] for i in range(m))\n        k, max_sq = 1, 0\n        for i in range(m):\n            ni = (i + 1) % m\n            while abs(self._cross(self.hull[i], self.hull[ni], self.hull[(k + 1) % m])) > abs(self._cross(self.hull[i], self.hull[ni], self.hull[k])):\n                k = (k + 1) % m\n            for pt in (self.hull[i], self.hull[ni]):\n                max_sq = max(max_sq, (pt[0] - self.hull[k][0]) ** 2 + (pt[1] - self.hull[k][1]) ** 2)\n        return {\"hull\": self.hull, \"area\": abs(area2) / 2.0, \"diameter\": round(math.sqrt(max_sq), 4)}\n\nhazards = [(2, 1), (8, 1), (10, 4), (6, 7), (1, 5), (5, 4), (4, 3)]\ngeo = GeofenceGeometryEngine(hazards)\nprint(\"Geofence Footprint:\", geo.report_footprint())\nprint(\"Hover (5, 4) inside zone?\", geo.contains_point((5, 4)))\nprint(\"Hover (0, 8) inside zone?\", geo.contains_point((0, 8)))\nprint(\"Route (0, 0) -> (11, 6) breaches zone?\", geo.route_breaches_zone((0, 0), (11, 6)))\nprint(\"Route (0, 8) -> (10, 9) breaches zone?\", geo.route_breaches_zone((0, 8), (10, 9)))",
