        "code": "import hashlib\n\nclass CountMinSketch:\n    def __init__(self, depth: int = 5, width: int = 128):\n        self.d = depth\n        self.w = width\n        self.table = [[0] * width for _ in range(depth)]\n\n    def _row_idx(self, row: int, key: str) -> int:\n        # Derive deterministic row-salted bucket via SHA-256\n        h = hashlib.sha256(f\"{row}:{key}\".encode(\"utf-8\")).digest()\n        return int.from_bytes(h[:8], \"big\") % self.w\n\n    def add(self, key: str, count: int = 1) -> None:\n        for r in range(self.d):\n            self.table[r][self._row_idx(r, key)] += count\n\n    def query(self, key: str) -> int:\n        return min(self.table[r][self._row_idx(r, key)] for r in range(self.d))\n\ncms = CountMinSketch(depth=5, width=64)\nexact = {}\n\n# Simulate Zipf-like stream: a few heavy hitters + 300 distinct low-traffic endpoints\nevents = ([\"/api/checkout\"] * 450 + [\"/api/search\"] * 280 + [\"/api/login\"] * 120 + [f\"/user/{i}\" for i in range(300)])\nfor ep in events:\n    cms.add(ep, 1)\n    exact[ep] = exact.get(ep, 0) + 1\n\nfor probe in [\"/api/checkout\", \"/api/search\", \"/api/login\", \"/user/42\", \"/never-seen\"]:\n    est = cms.query(probe)\n    tru = exact.get(probe, 0)\n    print(f\"{probe:15s} -> exact={tru:3d}, CMS_est={est:3d} (overcount={est - tru})\")\nassert all(cms.query(k) >= v for k, v in exact.items()), \"CMS must NEVER undercount!\"",
