        "code": "import hashlib\nimport math\nimport random\n\nclass Stage3StreamMonitor:\n    def __init__(self, expected: int = 300, k_sample: int = 4, seed: int = 42):\n        self.m = max(64, int(-expected * math.log(0.02) / (math.log(2) ** 2)))\n        self.k_bf = max(1, round((self.m / expected) * math.log(2)))\n        self.bf = bytearray((self.m + 7) // 8)\n        self.cms_d, self.cms_w = 4, 64\n        self.cms = [[0] * self.cms_w for _ in range(self.cms_d)]\n        self.hll_b = 6\n        self.regs = [0] * (1 << self.hll_b)\n        self.k_sample = k_sample\n        self.rng = random.Random(seed)\n        self.reservoir = []\n        self.seen = 0\n        self.replays = 0\n\n    def process(self, req_id: str, tag: str) -> None:\n        dg = hashlib.sha256(req_id.encode(\"utf-8\")).digest()\n        h1, h2 = int.from_bytes(dg[:8], \"big\"), int.from_bytes(dg[8:16], \"big\") | 1\n        if all((self.bf[((h1 + j * h2) % self.m) >> 3] >> (((h1 + j * h2) % self.m) & 7)) & 1 for j in range(self.k_bf)):\n            self.replays += 1\n        for j in range(self.k_bf):\n            p = (h1 + j * h2) % self.m\n            self.bf[p >> 3] |= (1 << (p & 7))\n\n        for r in range(self.cms_d):\n            idx = int.from_bytes(hashlib.sha256(f\"{r}:{tag}\".encode(\"utf-8\")).digest()[:8], \"big\") % self.cms_w\n            self.cms[r][idx] += 1\n\n        h64 = int.from_bytes(dg[16:24], \"big\")\n        b_idx = h64 >> (64 - self.hll_b)\n        w = h64 & ((1 << (64 - self.hll_b)) - 1)\n        rho = (64 - self.hll_b + 1) if w == 0 else ((64 - self.hll_b) - w.bit_length() + 1)\n        self.regs[b_idx] = max(self.regs[b_idx], rho)\n\n        if self.seen < self.k_sample:\n            self.reservoir.append((req_id, tag))\n        else:\n            j = self.rng.randint(0, self.seen)\n            if j < self.k_sample:\n                self.reservoir[j] = (req_id, tag)\n        self.seen += 1\n\n    def report(self, probe_tags: list[str]) -> dict:\n        m = 1 << self.hll_b\n        alpha = 0.7213 / (1.0 + 1.079 / m)\n        raw = alpha * (m ** 2) / sum(2.0 ** (-r) for r in self.regs)\n        z = self.regs.count(0)\n        uniq = round(m * math.log(m / z)) if raw <= 2.5 * m and z else round(raw)\n        freq = {\n            t: min(self.cms[r][int.from_bytes(hashlib.sha256(f\"{r}:{t}\".encode(\"utf-8\")).digest()[:8], \"big\") % self.cms_w] for r in range(self.cms_d))\n            for t in probe_tags\n        }\n        return {\"events\": self.seen, \"replays\": self.replays, \"est_unique\": uniq, \"tag_freqs\": freq, \"sample\": self.reservoir}\n\nmon3 = Stage3StreamMonitor(expected=300, k_sample=4, seed=42)\nfor i in range(360):\n    mon3.process(f\"tx-{i % 180}\", \"/pay\" if i % 4 == 0 else (\"/search\" if i % 3 == 0 else \"/browse\"))\nprint(\"Stage 3 Stream Report:\", mon3.report([\"/pay\", \"/search\", \"/browse\"]))",
