        "code": "class DLNode:\n    def __init__(self, key: str = \"\", val: int = 0):\n        self.key = key\n        self.val = val\n        self.freq = 1\n        self.prev: DLNode | None = None\n        self.next: DLNode | None = None\n\nclass SentinelDLL:\n    def __init__(self):\n        self.head = DLNode()\n        self.tail = DLNode()\n        self.head.next = self.tail\n        self.tail.prev = self.head\n        self.size = 0\n\n    def append_mru(self, node: DLNode) -> None:\n        # Insert directly right before tail sentinel (most-recently-used end)\n        prev_last = self.tail.prev\n        prev_last.next = node\n        node.prev = prev_last\n        node.next = self.tail\n        self.tail.prev = node\n        self.size += 1\n\n    def remove(self, node: DLNode) -> None:\n        p, n = node.prev, node.next\n        p.next = n\n        n.prev = p\n        node.prev = None\n        node.next = None\n        self.size -= 1\n\n    def pop_lru(self) -> DLNode | None:\n        if self.size == 0:\n            return None\n        victim = self.head.next\n        self.remove(victim)\n        return victim\n\n    def snapshot(self) -> list[tuple[str, int]]:\n        out, cur = [], self.head.next\n        while cur is not self.tail:\n            out.append((cur.key, cur.val))\n            cur = cur.next\n        return out\n\ndll = SentinelDLL()\nnodes = {k: DLNode(k, v) for k, v in [(\"a\", 1), (\"b\", 2), (\"c\", 3)]}\nfor k in [\"a\", \"b\", \"c\"]:\n    dll.append_mru(nodes[k])\nprint(\"Initial LRU->MRU order:\", dll.snapshot())\ndll.remove(nodes[\"a\"])\ndll.append_mru(nodes[\"a\"])\nprint(\"After accessing 'a' (promoted to MRU):\", dll.snapshot())\nevicted = dll.pop_lru()\nprint(\"Evicted LRU key:\", evicted.key, \"Remaining:\", dll.snapshot())",
