        "code": "from collections import OrderedDict\n\nclass LRUNode:\n    def __init__(self, key: int = 0, val: int = 0):\n        self.key, self.val = key, val\n        self.prev = self.next = None\n\nclass LRUCache:\n    def __init__(self, capacity: int):\n        self.cap = capacity\n        self.map: dict[int, LRUNode] = {}\n        self.head, self.tail = LRUNode(), LRUNode()\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n    def _unlink(self, node: LRUNode) -> None:\n        node.prev.next = node.next\n        node.next.prev = node.prev\n\n    def _push_mru(self, node: LRUNode) -> None:\n        p = self.tail.prev\n        p.next = node\n        node.prev = p\n        node.next = self.tail\n        self.tail.prev = node\n\n    def get(self, key: int) -> int:\n        if key not in self.map:\n            return -1\n        node = self.map[key]\n        self._unlink(node)\n        self._push_mru(node)\n        return node.val\n\n    def put(self, key: int, value: int) -> None:\n        if self.cap <= 0:\n            return\n        if key in self.map:\n            node = self.map[key]\n            node.val = value\n            self._unlink(node)\n            self._push_mru(node)\n            return\n        if len(self.map) == self.cap:\n            victim = self.head.next\n            self._unlink(victim)\n            del self.map[victim.key]\n        fresh = LRUNode(key, value)\n        self.map[key] = fresh\n        self._push_mru(fresh)\n\n# Verify exact parity against OrderedDict baseline\nlru = LRUCache(3)\nref = OrderedDict()\nops = [(\"put\", 1, 10), (\"put\", 2, 20), (\"put\", 3, 30), (\"get\", 1, 0), (\"put\", 4, 40), (\"get\", 2, 0), (\"get\", 3, 0), (\"put\", 5, 50), (\"get\", 1, 0)]\nresults = []\nfor kind, k, v in ops:\n    if kind == \"put\":\n        lru.put(k, v)\n        if k in ref: ref.move_to_end(k)\n        elif len(ref) == 3: ref.popitem(last=False)\n        ref[k] = v\n    else:\n        got_custom = lru.get(k)\n        got_ref = -1 if k not in ref else (ref.move_to_end(k) or ref[k])\n        assert got_custom == got_ref\n        results.append((k, got_custom))\nprint(\"Exact OrderedDict Parity Confirmed on Gets:\", results)\nprint(\"Final Cache Keys (LRU->MRU):\", list(ref.keys()))",
