        "code": "from collections import defaultdict\n\nclass LFUNode:\n    def __init__(self, key: int = 0, val: int = 0):\n        self.key, self.val, self.freq = key, val, 1\n        self.prev = self.next = None\n\nclass FreqDLL:\n    def __init__(self):\n        self.head, self.tail = LFUNode(), LFUNode()\n        self.head.next = self.tail\n        self.tail.prev = self.head\n        self.size = 0\n\n    def append(self, node: LFUNode) -> None:\n        p = self.tail.prev\n        p.next = node; node.prev = p; node.next = self.tail; self.tail.prev = node\n        self.size += 1\n\n    def remove(self, node: LFUNode) -> None:\n        node.prev.next = node.next; node.next.prev = node.prev\n        node.prev = node.next = None\n        self.size -= 1\n\n    def pop_lru(self) -> LFUNode:\n        v = self.head.next\n        self.remove(v)\n        return v\n\nclass LFUCache:\n    def __init__(self, capacity: int):\n        self.cap = capacity\n        self.key_map: dict[int, LFUNode] = {}\n        self.freq_map: dict[int, FreqDLL] = defaultdict(FreqDLL)\n        self.min_freq = 0\n\n    def _bump(self, node: LFUNode) -> None:\n        f = node.freq\n        self.freq_map[f].remove(node)\n        if f == self.min_freq and self.freq_map[f].size == 0:\n            self.min_freq += 1\n        node.freq += 1\n        self.freq_map[node.freq].append(node)\n\n    def get(self, key: int) -> int:\n        if key not in self.key_map:\n            return -1\n        node = self.key_map[key]\n        self._bump(node)\n        return node.val\n\n    def put(self, key: int, value: int) -> int | None:\n        if self.cap <= 0:\n            return None\n        if key in self.key_map:\n            node = self.key_map[key]\n            node.val = value\n            self._bump(node)\n            return None\n        evicted_key = None\n        if len(self.key_map) == self.cap:\n            victim = self.freq_map[self.min_freq].pop_lru()\n            del self.key_map[victim.key]\n            evicted_key = victim.key\n        fresh = LFUNode(key, value)\n        self.key_map[key] = fresh\n        self.freq_map[1].append(fresh)\n        self.min_freq = 1\n        return evicted_key\n\nlfu = LFUCache(2)\nlfu.put(1, 100); lfu.put(2, 200)\nlfu.get(1)  # Key 1 rises to freq=2 while key 2 stays at freq=1 (min_freq=1)\nlfu.get(1)  # Key 1 reaches freq=3\nev1 = lfu.put(3, 300)  # Evicts key 2 (freq=1 < freq=3), sets min_freq=1\nev2 = lfu.put(4, 400)  # Key 3 (freq=1) and Key 4 entering: key 3 evicted, hot Key 1 preserved!\nprint(f\"Evicted cold peers: {ev1}, {ev2}; Hot Key 1 remains: get(1)={lfu.get(1)}, min_freq={lfu.min_freq}\")",
