        "code": "import random\n\nclass LevelHistogramAuditor:\n    def __init__(self, p: float = 0.5, max_level: int = 12, seed: int = 42):\n        self.p = p\n        self.max_level = max_level\n        self.rng = random.Random(seed)\n\n    def sample_level(self) -> int:\n        lvl = 0\n        while self.rng.random() < self.p and lvl < self.max_level:\n            lvl += 1\n        return lvl\n\n    def audit_distribution(self, count: int) -> tuple[list[int], int]:\n        layer_counts = [0] * (self.max_level + 1)\n        total_pointers = 0\n        for _ in range(count):\n            h = self.sample_level()\n            total_pointers += h + 1\n            for lvl in range(h + 1):\n                layer_counts[lvl] += 1\n        while len(layer_counts) > 1 and layer_counts[-1] == 0:\n            layer_counts.pop()\n        return layer_counts, total_pointers\n\nauditor = LevelHistogramAuditor(p=0.5, max_level=10, seed=42)\ncounts, ptrs = auditor.audit_distribution(200)\nprint(\"Nodes reaching each level [L0..Lk]:\", counts)\nprint(f\"Total pointers allocated = {ptrs} across 200 items ({ptrs / 200:.2f} ptrs/node, theoretical ~2.00)\")",
