        "code": "import random\n\nclass InsertableSkipList:\n    def __init__(self, max_level: int = 8, p: float = 0.5, seed: int = 42):\n        self.max_level = max_level\n        self.p = p\n        self.rng = random.Random(seed)\n        self.level = 0\n        self.header = [-10**18, None, [None] * (max_level + 1)]  # [key, val, forward]\n\n    def _random_level(self) -> int:\n        lvl = 0\n        while self.rng.random() < self.p and lvl < self.max_level:\n            lvl += 1\n        return lvl\n\n    def insert(self, key: int, val: str) -> None:\n        update = [None] * (self.max_level + 1)\n        curr = self.header\n        for i in range(self.level, -1, -1):\n            while curr[2][i] is not None and curr[2][i][0] < key:\n                curr = curr[2][i]\n            update[i] = curr\n\n        cand = curr[2][0]\n        if cand is not None and cand[0] == key:\n            cand[1] = val\n            return\n\n        new_lvl = self._random_level()\n        if new_lvl > self.level:\n            for i in range(self.level + 1, new_lvl + 1):\n                update[i] = self.header\n            self.level = new_lvl\n\n        new_node = [key, val, [None] * (new_lvl + 1)]\n        for i in range(new_lvl + 1):\n            new_node[2][i] = update[i][2][i]\n            update[i][2][i] = new_node\n\n    def level_view(self) -> dict[int, list[int]]:\n        view = {}\n        for lvl in range(self.level, -1, -1):\n            keys, cur = [], self.header[2][lvl]\n            while cur is not None:\n                keys.append(cur[0])\n                cur = cur[2][lvl]\n            view[lvl] = keys\n        return view\n\nsl = InsertableSkipList(seed=42)\nfor x in [50, 10, 80, 30, 20, 70, 40, 60]:\n    sl.insert(x, f\"item_{x}\")\nprint(\"Sorted Base & Express Layers (Seed=42):\")\nfor lvl, keys in sl.level_view().items():\n    print(f\"  Level {lvl}: {keys}\")",
