        "code": "import random\n\nclass FullSkipList:\n    class _Node:\n        def __init__(self, key: int, val: str, lvl: int):\n            self.key, self.val = key, val\n            self.forward: list[FullSkipList._Node | None] = [None] * (lvl + 1)\n\n    def __init__(self, max_level: int = 10, p: float = 0.5, seed: int = 42):\n        self.max_level, self.p = max_level, p\n        self.rng = random.Random(seed)\n        self.level = 0\n        self.header = self._Node(-10**18, \"\", max_level)\n\n    def insert(self, key: int, val: str) -> None:\n        update = [self.header] * (self.max_level + 1)\n        cur = self.header\n        for i in range(self.level, -1, -1):\n            while cur.forward[i] is not None and cur.forward[i].key < key:\n                cur = cur.forward[i]\n            update[i] = cur\n        if cur.forward[0] is not None and cur.forward[0].key == key:\n            cur.forward[0].val = val\n            return\n        lvl = 0\n        while self.rng.random() < self.p and lvl < self.max_level:\n            lvl += 1\n        if lvl > self.level:\n            self.level = lvl\n        node = self._Node(key, val, lvl)\n        for i in range(lvl + 1):\n            node.forward[i] = update[i].forward[i]\n            update[i].forward[i] = node\n\n    def delete(self, key: int) -> bool:\n        update = [self.header] * (self.level + 1)\n        cur = self.header\n        for i in range(self.level, -1, -1):\n            while cur.forward[i] is not None and cur.forward[i].key < key:\n                cur = cur.forward[i]\n            update[i] = cur\n        target = cur.forward[0]\n        if target is None or target.key != key:\n            return False\n        for i in range(self.level + 1):\n            if update[i].forward[i] is not target:\n                break\n            update[i].forward[i] = target.forward[i]\n        while self.level > 0 and self.header.forward[self.level] is None:\n            self.level -= 1\n        return True\n\n    def range_scan(self, lo: int, hi: int) -> list[tuple[int, str]]:\n        cur = self.header\n        for i in range(self.level, -1, -1):\n            while cur.forward[i] is not None and cur.forward[i].key < lo:\n                cur = cur.forward[i]\n        cur = cur.forward[0]\n        out = []\n        while cur is not None and cur.key <= hi:\n            out.append((cur.key, cur.val))\n            cur = cur.forward[0]\n        return out\n\nsl = FullSkipList(seed=42)\nfor k in [15, 3, 27, 9, 42, 18, 33, 6]:\n    sl.insert(k, f\"v{k}\")\nprint(\"Range [9, 30] before delete:\", sl.range_scan(9, 30))\nprint(\"Delete 18:\", sl.delete(18), \"| Delete 99:\", sl.delete(99))\nprint(\"Range [9, 30] after delete: \", sl.range_scan(9, 30), \"| Active max level:\", sl.level)",
