        "code": "import bisect\nimport hashlib\n\nclass BaseHashRing:\n    def __init__(self, nodes: list[str]):\n        self.pos_to_node: dict[int, str] = {}\n        for nd in nodes:\n            h = self._h(nd)\n            self.pos_to_node[h] = nd\n        self.ring = sorted(self.pos_to_node.keys())\n\n    @staticmethod\n    def _h(s: str) -> int:\n        return int(hashlib.md5(s.encode(\"utf-8\")).hexdigest()[:8], 16)\n\n    def get_node(self, key: str) -> str:\n        h = self._h(key)\n        idx = bisect.bisect_right(self.ring, h)\n        if idx == len(self.ring):\n            idx = 0  # Clockwise wrap past 2^32 back to ring[0]\n        return self.pos_to_node[self.ring[idx]]\n\nring_4 = BaseHashRing([\"shard-0\", \"shard-1\", \"shard-2\", \"shard-3\"])\nring_5 = BaseHashRing([\"shard-0\", \"shard-1\", \"shard-2\", \"shard-3\", \"shard-4\"])\n\nkeys = [f\"session:{i}\" for i in range(1000)]\nmoved = sum(1 for k in keys if ring_4.get_node(k) != ring_5.get_node(k))\ndist = {nd: 0 for nd in [\"shard-0\", \"shard-1\", \"shard-2\", \"shard-3\"]}\nfor k in keys:\n    dist[ring_4.get_node(k)] += 1\n\nprint(f\"Ring 4 -> 5 key displacement = {moved}/1000 ({moved / 10:.1f}% vs 80% modulo!)\")\nprint(\"WAIT - look at raw non-vnode shard skew across 4 nodes:\", dist)",
