        "code": "import heapq\n\ndef brute_knapsack_nodes(items: list[tuple[int, int]], cap: int) -> tuple[int, int]:\n    nodes = 0\n    best = 0\n    n = len(items)\n    def dfs(i: int, w: int, v: int) -> None:\n        nonlocal nodes, best\n        nodes += 1\n        if v > best: best = v\n        if i == n: return\n        wt, val = items[i]\n        if w + wt <= cap:\n            dfs(i + 1, w + wt, v + val)\n        dfs(i + 1, w, v)\n    dfs(0, 0, 0)\n    return best, nodes\n\ndef branch_and_bound_knapsack(items: list[tuple[int, int]], cap: int) -> tuple[int, int, int]:\n    # items: (weight, value) -> sort descending by value/weight efficiency\n    ordered = sorted(items, key=lambda x: x[1] / x[0], reverse=True)\n    n = len(ordered)\n\n    def upper_bound(idx: int, cur_w: int, cur_v: int) -> float:\n        if cur_w >= cap:\n            return float(cur_v)\n        rem = cap - cur_w\n        ub = float(cur_v)\n        for j in range(idx, n):\n            wt, val = ordered[j]\n            if wt <= rem:\n                rem -= wt\n                ub += val\n            else:\n                ub += (val / wt) * rem\n                break\n        return ub\n\n    best_val = 0\n    expanded = pruned = 0\n    # Max-heap via negated upper bound: (-ub, idx, cur_w, cur_v)\n    pq = [(-upper_bound(0, 0, 0), 0, 0, 0)]\n    while pq:\n        neg_ub, i, w, v = heapq.heappop(pq)\n        ub = -neg_ub\n        if ub <= best_val:\n            pruned += 1\n            continue\n        expanded += 1\n        if v > best_val:\n            best_val = v\n        if i == n:\n            continue\n        wt, val = ordered[i]\n        if w + wt <= cap:\n            nv = v + val\n            if nv > best_val: best_val = nv\n            c_ub = upper_bound(i + 1, w + wt, nv)\n            if c_ub > best_val: heapq.heappush(pq, (-c_ub, i + 1, w + wt, nv))\n            else: pruned += 1\n        skip_ub = upper_bound(i + 1, w, v)\n        if skip_ub > best_val: heapq.heappush(pq, (-skip_ub, i + 1, w, v))\n        else: pruned += 1\n    return best_val, expanded, pruned\n\nsample = [(4, 40), (7, 42), (5, 25), (3, 12), (2, 11), (6, 33), (8, 45), (5, 29)]\nb_val, b_nodes = brute_knapsack_nodes(sample, 15)\nbb_val, bb_exp, bb_pruned = branch_and_bound_knapsack(sample, 15)\nassert b_val == bb_val\nprint(f\"Optimal Value Matched = {bb_val}\")\nprint(f\"Brute DFS Nodes: {b_nodes} vs Best-First B&B Expanded={bb_exp}, Pruned={bb_pruned}\")",
