        "code": "import heapq\n\ndef solve_grid(grid: list[str], start: tuple[int, int], goal: tuple[int, int], mode: str) -> tuple[int, int]:\n    R, C = len(grid), len(grid[0])\n    def h(r: int, c: int) -> int:\n        return abs(r - goal[0]) + abs(c - goal[1])\n\n    def priority(g: int, r: int, c: int) -> int:\n        if mode == \"dijkstra\": return g\n        if mode == \"greedy\": return h(r, c)\n        return g + h(r, c)  # A*\n\n    best_g = {start: 0}\n    pq = [(priority(0, start[0], start[1]), 0, start[0], start[1])]\n    visited = set()\n    popped = 0\n\n    while pq:\n        _, g, r, c = heapq.heappop(pq)\n        if (r, c) in visited:\n            continue\n        visited.add((r, c))\n        popped += 1\n        if (r, c) == goal:\n            return g, popped\n        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:\n            nr, nc = r + dr, c + dc\n            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != \"#\":\n                ng = g + 1\n                if ng < best_g.get((nr, nc), 10**9):\n                    best_g[(nr, nc)] = ng\n                    heapq.heappush(pq, (priority(ng, nr, nc), ng, nr, nc))\n    return -1, popped\n\nu_wall = [\n    \".........\",\n    \"..#####..\",\n    \"..#...#..\",\n    \"......#..\",\n    \"..#####..\",\n    \".........\",\n]\nstart, goal = (2, 1), (2, 8)\nfor mode in [\"dijkstra\", \"greedy\", \"astar\"]:\n    dist, exp = solve_grid(u_wall, start, goal, mode)\n    print(f\"{mode:10s} -> path_steps={dist}, popped_nodes={exp}\")",
