        "code": "import heapq\n\ndef run_astar_with_scale(grid: list[str], start: tuple[int, int], goal: tuple[int, int], h_scale: float) -> tuple[int, int]:\n    R, C = len(grid), len(grid[0])\n    # NOTE: h_scale <= 1.0 -> Admissible & Consistent! h_scale > 1.0 (Weighted A*) -> Inadmissible!\n    pq = [(h_scale * (abs(start[0] - goal[0]) + abs(start[1] - goal[1])), 0, start)]\n    best_g = {start: 0}\n    closed = set()\n    popped = 0\n\n    while pq:\n        _, g, (r, c) = heapq.heappop(pq)\n        if (r, c) in closed:\n            continue\n        closed.add((r, c))\n        popped += 1\n        if (r, c) == goal:\n            return g, popped\n        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:\n            nr, nc = r + dr, c + dc\n            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] != \"#\":\n                ng = g + 1\n                if ng < best_g.get((nr, nc), 10**9):\n                    best_g[(nr, nc)] = ng\n                    h_val = h_scale * (abs(nr - goal[0]) + abs(nc - goal[1]))\n                    heapq.heappush(pq, (ng + h_val, ng, (nr, nc)))\n    return -1, popped\n\n# Trap grid: direct short detour has slight initial step away from goal; bad side detour goes initially toward goal\ntrap = [\n    \".#.....\",\n    \".#.###.\",\n    \".#.#...\",\n    \"...#.#.\",\n    \"#####..\",\n]\ns, g = (2, 0), (0, 6)\n# Note true optimal path: down (3,0)->(3,1)->(3,2)->up (0,2)? Wall at row 4 blocks south, let's test open spiral:\nspiral = [\n    \".......\",\n    \".#####.\",\n    \".....#.\",\n    \"####.#.\",\n    \".......\",\n]\nfor scale in [0.0, 1.0, 3.0]:\n    dist, exp = run_astar_with_scale(spiral, (2, 0), (4, 6), scale)\n    label = \"Dijkstra (h=0)\" if scale == 0 else (\"A* Admissible (h=1x)\" if scale == 1 else \"Weighted Inadmissible (h=3x)\")\n    print(f\"{label:28s}: cost={dist:2d}, popped={exp:2d}\")",
