        "code": "import heapq\n\nclass OptimizationAndPathEngine:\n    @staticmethod\n    def route_agv(warehouse: list[str], start: tuple[int, int], goal: tuple[int, int]) -> dict:\n        R, C = len(warehouse), len(warehouse[0])\n        def search(use_h: bool):\n            def prio(g_val: int, r: int, c: int):\n                hv = abs(r - goal[0]) + abs(c - goal[1]) if use_h else 0\n                return (g_val + hv, -g_val, r, c) if use_h else (g_val, r, c)\n\n            pq = [(prio(0, start[0], start[1]), 0, start[0], start[1])]\n            best_g = {start: 0}\n            parent = {start: None}\n            closed = set()\n            popped = 0\n            while pq:\n                _, g, r, c = heapq.heappop(pq)\n                if (r, c) in closed: continue\n                closed.add((r, c)); popped += 1\n                if (r, c) == goal:\n                    path, cur = [], goal\n                    while cur is not None: path.append(cur); cur = parent[cur]\n                    return g, popped, list(reversed(path))\n                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:\n                    nr, nc = r + dr, c + dc\n                    if 0 <= nr < R and 0 <= nc < C and warehouse[nr][nc] != \"#\":\n                        ng = g + 1\n                        if ng < best_g.get((nr, nc), 10**9):\n                            best_g[(nr, nc)] = ng; parent[(nr, nc)] = (r, c)\n                            heapq.heappush(pq, (prio(ng, nr, nc), ng, nr, nc))\n            return -1, popped, []\n\n        d_cost, d_pop, _ = search(use_h=False)\n        a_cost, a_pop, a_path = search(use_h=True)\n        assert d_cost == a_cost\n        return {\"steps\": a_cost, \"astar_popped\": a_pop, \"dijkstra_popped\": d_pop, \"saved_pct\": round((1 - a_pop / max(1, d_pop)) * 100, 1), \"path_len\": len(a_path)}\n\n    @staticmethod\n    def optimize_cargo(crates: list[tuple[str, int, int]], max_kg: int) -> dict:\n        # crates: (id, kg, value)\n        ordered = sorted(crates, key=lambda x: x[2] / x[1], reverse=True)\n        n = len(ordered)\n        def bound(idx: int, w: int, val: int) -> float:\n            rem, ub = max_kg - w, float(val)\n            for j in range(idx, n):\n                _, wt, vl = ordered[j]\n                if wt <= rem: rem -= wt; ub += vl\n                else: ub += (vl / wt) * rem; break\n            return ub\n\n        best_val, best_pick = 0, ()\n        expanded = pruned = 0\n        pq = [(-bound(0, 0, 0), 0, 0, 0, ())]\n        while pq:\n            neg_ub, i, w, v, picked = heapq.heappop(pq)\n            if -neg_ub <= best_val:\n                pruned += 1; continue\n            expanded += 1\n            if v > best_val: best_val, best_pick = v, picked\n            if i == n: continue\n            cid, wt, vl = ordered[i]\n            if w + wt <= max_kg:\n                np = picked + (cid,)\n                if v + vl > best_val: best_val, best_pick = v + vl, np\n                cb = bound(i + 1, w + wt, v + vl)\n                if cb > best_val: heapq.heappush(pq, (-cb, i + 1, w + wt, v + vl, np))\n                else: pruned += 1\n            sb = bound(i + 1, w, v)\n            if sb > best_val: heapq.heappush(pq, (-sb, i + 1, w, v, picked))\n            else: pruned += 1\n        return {\"max_value\": best_val, \"picked\": sorted(best_pick), \"expanded\": expanded, \"pruned\": pruned}\n\nwh = [\n    \"..........\",\n    \".###..###.\",\n    \"..........\",\n    \"...####...\",\n    \"..........\",\n    \".###..###.\",\n    \"..........\",\n]\ncrates = [(\"c1\", 6, 42), (\"c2\", 5, 34), (\"c3\", 4, 24), (\"c4\", 7, 40), (\"c5\", 3, 19), (\"c6\", 2, 11)]\nprint(\"1. A* AGV Route Audit:\", OptimizationAndPathEngine.route_agv(wh, (6, 0), (0, 9)))\nprint(\"2. B&B Cargo Pack Audit:\", OptimizationAndPathEngine.optimize_cargo(crates, max_kg=12))",
